#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n <= 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 30) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    long long cat[30];
    cat[0] = 1;
    for (int i = 1; i < n; ++i) {
        long long sum = 0;
        for (int j = 0; j < i; ++j) {
            sum += cat[j] * cat[i - 1 - j];
        }
        cat[i] = sum;
    }
    printf("%lld\n", cat[n - 1]);
    return 0;
}
